// @suss/framework-graphql-ruby: RubyPack for graphql-ruby's class-based
// field DSL.
//
// graphql-ruby declares a GraphQL type as a Ruby class extending a
// project's own base object class (generated by `rails g graphql:install`
// as `Types::BaseObject`, itself extending `GraphQL::Schema::Object`),
// with each field declared by a `field` call in the class body. The
// GraphQL type name comes from the class's own short name with a
// trailing `Type` stripped, the library's own `default_graphql_name`
// convention, which the pack selects as the adapter's `stripTypeSuffix`
// naming. Root Query/Mutation fields wired through `mutation:` /
// `resolver:` read their declared shape from the referenced class's own
// file, located by the Rails constant-to-path convention (the adapter's
// `railsUnderscore`) under `root`. Everything graphql-ruby names, the
// `field`/`type`/`argument` calls, the `required:` and `camelize:`
// keywords and their defaults, the built-in scalars and their
// `GraphQL::Types::` spelling, is stated here; the adapter reads only
// these fields.
//
// v0 scope: discovery and declared-shape reading only, per the
// language-adapters proposal's Ruby slice. `routes.rb` is a separate,
// much larger macro-expansion problem and is out of scope here.

import path from "node:path";

import { SCALAR_SHAPES } from "@suss/contract-graphql";

import type { GraphqlObjectFields, RubyPack } from "@suss/adapter-ruby";

export interface GraphqlRubyPackOptions {
  /**
   * Directory the Rails constant-to-path convention resolves a
   * `mutation:` / `resolver:` field's referenced class against, e.g.
   * `path.join(repoRoot, "app/graphql")`. A project's own directory
   * layout, not something graphql-ruby names, so there is no default.
   *
   * Written relative, it is read relative to the file it was written
   * in when it came from a pack config file, and relative to the
   * working directory otherwise. So `app/graphql` in a config file at
   * the repository root means the same directory whichever directory
   * the command runs from.
   */
  root: string;
  /**
   * Where the config file holding these options sits, supplied by
   * whatever read that file rather than written in it. A relative
   * `root` is resolved against this.
   */
  configDirectory?: string;
  /**
   * Base class names beyond graphql-ruby's own generated
   * `Types::BaseObject` that also mark a class as declaring GraphQL
   * fields, e.g. a project's own intermediate base type. Named here the
   * way flask-restx's `wrapperModules` names a project's wrapper
   * alongside the library's own module.
   */
  baseClassNames?: string[];
  /**
   * graphql-ruby's own default for exposing a `field`/`argument`
   * symbol's snake_case name as camelCase on the schema. Defaults to
   * `true`, matching the library's own default; set to `false` when a
   * project's schema configures `camelize: false` schema-wide. A
   * `field` or `argument` call's own `camelize:` keyword always
   * overrides this for that one name, the same as it overrides
   * graphql-ruby's schema-wide setting at runtime.
   */
  camelize?: boolean;
}

/**
 * `Types::BaseObject` is graphql-ruby's own scaffolded convention: the
 * Rails generator that sets up a graphql-ruby project creates exactly
 * this class, extending `GraphQL::Schema::Object`, for every object
 * type in the schema to extend. It is the library's own naming, not a
 * particular project's choice, the same way flask-restx's `route` is
 * accepted as a default without a project naming it.
 */
const DEFAULT_BASE_CLASS_NAMES = ["Types::BaseObject"];

/**
 * Where a wired field's class is looked up, as an absolute directory.
 *
 * A `root` written in a config file is written relative to that file,
 * which is the one thing whoever wrote it can be sure of. Reading it
 * relative to the working directory instead means the same config
 * works from the project root and finds nothing from anywhere else,
 * and finding nothing looks exactly like a schema whose fields are all
 * unwired.
 */
function rootDirectory(options: GraphqlRubyPackOptions): string {
  if (options.configDirectory === undefined || path.isAbsolute(options.root)) {
    return options.root;
  }
  return path.resolve(options.configDirectory, options.root);
}

export function graphqlRubyFramework(
  options: GraphqlRubyPackOptions,
): RubyPack {
  // A caller with no types in front of it, the CLI holding a pack
  // config somebody wrote by hand, can arrive here with nothing. This
  // pack cannot read a wired field's class without knowing the
  // directory to look it up under, and reading half a schema without
  // saying so is worse than refusing.
  if (typeof options?.root !== "string" || options.root === "") {
    throw new Error(
      "it needs `root`, the directory a wired field's class is looked up under, and no default can be right: that is this project's own directory layout. A Rails app generated by the library keeps it at app/graphql.",
    );
  }

  const pattern: GraphqlObjectFields = {
    type: "graphqlObjectFields",
    baseClassNames: [
      ...DEFAULT_BASE_CLASS_NAMES,
      ...(options.baseClassNames ?? []),
    ],
    root: rootDirectory(options),
    pathConvention: "railsUnderscore",
    fieldCallName: "field",
    typeCallName: "type",
    argumentCallName: "argument",
    wiringKeywords: ["mutation", "resolver"],
    resolverMethodName: "resolve",
    requiredKeyword: "required",
    // graphql-ruby registers an argument as required unless the call
    // opts out with `required: false`; the library's own default, not
    // a guess about project code.
    requiredDefault: true,
    camelizeKeyword: "camelize",
    camelizeDefault: options.camelize ?? true,
    // The five standard scalars come from @suss/contract-graphql's own
    // SDL table, so a contract read from Ruby compares against one
    // read from SDL without a vocabulary mismatch. `Integer` is
    // graphql-ruby's own addition: a native Ruby class the library
    // accepts as a convenience synonym for its `Int` scalar
    // (`field :age, Integer, null: true`), coerced internally the
    // same way `String` is.
    scalars: {
      ...SCALAR_SHAPES,
      Integer: { type: "number" },
    },
    scalarNamePrefixes: ["GraphQL::Types::"],
    typeNameConvention: "stripTypeSuffix",
  };
  return {
    name: "graphql-ruby",
    protocol: "http-graphql",
    discovery: [pattern],
  };
}

export default graphqlRubyFramework;
